/**
 * 筛选条件项
 */
  interface Criteria {
    /**
     * 筛选项字段值：
     * |值选项|描述|
     * |---|---|
     * |columnNumber|列号，从1开始|
     * |fieldId|字段id|
     */
    Field: any;
    /**
     * 筛选项规则（大小写不敏感）：
     * |枚举值|描述|
     * |---|---|
     * |Equals|等于|
     * |NotEqu|不等于|
     * |Greater|大于|
     * |GreaterEqu|大等于|
     * |Less|小于|
     * |LessEqu|小等于|
     * |GreaterEquAndLessEqu|介于（取等）|
     * |LessOrGreater|介于（不取等）|
     * |BeginWith|开头是|
     * |EndWith|结尾是|
     * |Contains|包含|
     * |NotContains|不包含|
     * |Intersected|指定值|
     * |Empty|为空|
     * |NotEmpty|不为空|
     */
    Op: any;
    /**
     * 筛选条件项值
     *
     *
     * 各筛选规则独立地限制了values数组内最多允许填写的元素数，当values内元素数超过阈值时，该筛选规则将失效。“为空、不为空”只允许在op为“Intersected”时填写。“介于”允许最多填写2个元素；“指定值”允许填写65535个元素；其他规则允许最多填写1个元素
     * values[]数组内的元素为字符串时，表示文本匹配。目前还支持对日期进行动态筛选，此时values[]内的元素需以结构体的形式给出：
     * ```
     * const dateValue = {"dynamicType": "lastMonth","type": "DynamicSimple"}
     * Criteria("@日期", "Equals", [dateValue])
     * ```
     * 上述示例对应的筛选条件为“等于上一个月”。
     * 要使用日期动态筛选，values[]内的结构体需要指定"type": "DynamicSimple"，当"op"为"equals"时，"dynamicType"可以为如下的值（大小写不敏感）：
     * |枚举值|描述|
     * |---|---|
     * |today|今天|
     * |yesterday|昨天|
     * |tomorrow|明天|
     * |last7Days|最近7天|
     * |last30Days|最近30天|
     * |thisWeek|本周|
     * |lastWeek|上周|
     * |nextWeek|下周|
     * |thisMonth|本月|
     * |lastMonth|上月|
     * |nextMonth|次月|
     *
     * 当"op"为"greater"或"less"时，"dynamicType"只能是昨天、今天或明天。
     *
     * 当"op"为"Intersected"时，value=[{type: 'Any'}]表示全选，value=[{type: '', value: ''}]表示空白
     *
     * 对不同字段类型，values会有不同的用法
     * 联系人字段:
     * ```
     * // value是一个结构体，指定type为 Contact, value 为用户id
     * const dateValue = {"type":"Contact", value:"user id"}
     * ```
     * 单/多选项字段:
     * ```
     * // value是一个结构体，指定type为 SelectItem, value 为选项的ID
     * const dateValue = {"type":"SelectItem", value:"B"}
     * ```
     */
    Value: any;
  }

/**
 * 单元格数据，读取单元格值时， 如果是复杂的字段数据，则会返回DBCellValue, 比如：多选项/超链接/联系人/级联字段/关联字段/地址字段/图片与附件。
 * 当通过RecordRange.Value 设置复杂的字段数据时，需要构造DBCellValue作为参数设置到单元格
 * ```
 * ActiveView.RecordRange([5,6], "@地址").Value = DBCellValue({districts:["广东省","珠海市","香洲区"],detail:"云海路"})
 * ```
 */
  interface DBCellValue {
    /**
     * 返回固定字符串 `DBCellValue`，用于标识该包装对象类型。
     */
    ClassName: string;
    /**
     * 返回单元格的值
     * 地址字段类型: 通过DBCellValue() 生成字段的数据
     * ```
     * DBCellValue({districts:["广东省","珠海市","香洲区"],detail:"前岛环路xxxx号"})
     * ```
     * 级联字段类型：通过DBCellValue() 生成字段的数据
     * ```
     * DBCellValue({districts:["广东省","珠海市","香洲区"]})
     * ```
     * 超链接字段类型：
     * ```
     * DBCellValue({address:"wps.cn", display:"wps"})
     * ```
     *
     * 关联字段类型: 参数传入关联的记录id
     * ```
     * DBCellValue(["b","V"])
     * ```
     *
     * 多选项类型：
     * ```
     * DBCellValue(["未,开始","进行中"])
     * ```
     *
     * 图片与附件字段：可以传入包含 URL/base64编码的图片/云文档 的数组，支持多个附件。
     * 注意：由于脚本有运行时长限制，附件较大/或者较多时会导致超时，设置失败
     * ```
     * DBCellValue([{fileData: url/base64, fileName: ""}])
     * ```
     */
    Value: any;
    /**
     * 当内部值为超链接对象且包含 `address` 字段时，返回链接 URL；否则返回 `null`。
     */
    address: string | null;
    /**
     * 当内部值为地址等对象且包含 `detail` 字段时，返回详细地址；否则返回 `null`。
     */
    detail: string | null;
    /**
     * 当内部值为超链接对象且包含 `display` 字段时，返回显示文本；否则返回 `null`。
     */
    display: string | null;
    /**
     * 当内部值为地址或级联等对象且包含 `districts` 字段时，返回省市区（或级联层级）数组；否则返回 `null`。
     */
    districts: any[];

    /**
     * 将内部包装的数据序列化为 JSON 字符串，格式为 `{"Value":...}`。
     *
     * @returns string
     */
    toString(): string;
  }

/**
 * DataSource 对象
 */
  interface DataSource {
    /**
     * 创建同步表
     *
     * @param FileId 在线表格文件的 fileId
     * @param OfficeType 在线表格文件的类型：d 代表多维表格，k 代表智能表格
     * @param SheetIds 在线表格文件的 stId 数组
     * @returns Sheet[]
     */
    CreateDBSyncSheets(FileId: string, OfficeType: 'd' | 'k', SheetIds: number[]): Sheet[];
    /**
     * 将数据源表合并成一个合并表。
     *
     * @param SummarySourceConfigs 数据源配置对象
     * @returns SummarySheet
     */
    CreateSummarySheet(SummarySourceConfigs: SummarySourceConfigs): SummarySheet;
    /**
     * 创建同步表
     *
     * @param FileId 在线表格文件的 fileId
     * @param OfficeType 在线表格文件的类型：d 代表多维表格，k 代表智能表格
     * @param SheetIds 在线表格文件的 stId 数组
     * @returns SyncDBSheet[]
     */
    CreateSyncDBSheets(FileId: string, OfficeType: 'd' | 'k', SheetIds: number[]): SyncDBSheet[];
    /**
     * 将在线表格文件导入为新的数据表
     *
     * @param FileId 在线表格文件的 fileId
     * @returns Sheet[]
     */
    ImportFromCloud(FileId: string): Sheet[];
    /**
     * 将本地表格文件导入为新的数据表
     *
     * @param File 本地表格文件对象
     * @returns Sheet[]
     */
    ImportFromLocal(File: any): Sheet[];
  }

/**
 * DateField 日期字段的属性，修改属性之后需要 FieldDescriptor 调用Apply()方法使得修改生效。如果非日期字段，无法设置相关属性
 */
  interface DateField {
    /**
     * 只对日期字段有效，是否在选择日期的面板上标识节假日
     */
    IsShowHoliday: boolean;
    /**
     * 字段类型为 日期 时，通过此属性可以设置是否显示时间
     */
    IsShowTime: boolean;
    /**
     * 字段类型为 日期 时，通过此属性设置是否显示星期
     */
    IsShowWeek: boolean;
  }

/**
 * DbComment对象的属性和方法可以用来操作该条评论。
 */
  interface DbComment {
    /**
     * 返回评论的Id
     */
    readonly Id: string;
    /**
     * 返回评论的文本
     */
    readonly Text: string;

    /**
     * 删除记录
     *
     * @returns boolean
     */
    Delete(): boolean;
  }

/**
 * 网格视图的列属性，提供修改列宽和隐藏/显示列的方法
 */
  interface Field {
    /**
     * 字段的数据定义
     */
    readonly FieldDescriptor: FieldDescriptor;
    /**
     * 视图字段的Id
     */
    readonly Id: string;
    /**
     * 视图字段的Name
     */
    readonly Name: string;
    /**
     * 视图字段的Type
     */
    readonly Type: string;
    /**
     * 视图的字段是否可见
     */
    Visible: boolean;
    /**
     * 视图字段的Width
     */
    readonly Width: string;

    /**
     * 复制当前字段到指定位置
     *
     * @param Before 在Before之前插入复制字段
     * @param After 在After之后插入复制字段
     * @returns this
     */
    Copy(Before?: string | number, After?: string | number): this;
    /**
     * 移动字段到指定位置
     *
     * @param Before 移动到Before字段之前
     * @param After 移动到After字段之后
     * @returns ApiResult
     */
    Move(Before?: string | number, After?: string | number): ApiResult;
  }

/**
 * FieldDescriptor 描述了字段的属性，可以通过SetType修改字段的类型，修改属性之后需要主动调用Apply()方法使得修改生效。
 * 每次读取FieldDescriptor都会重新生成数据，所以修改前需要记录下当前的FieldDescriptor，才能正确调用Apply()
 * ```
 * const fieldDescriptor = Sheets(1).FieldDescriptors(1)
 * // 设置属性
 * // ....
 * fieldDescriptor.Apply()
 * ```
 *
 * 不同的字段类型有不同的属性设置，不是对应的字段类型，获取相关的属性时会返回null，无法正常设置
 * |字段类型|特有的字段属性|
 * |----|----|
 * |按钮字段|[Button](/app-integration-dev/guide/dbsheet/Api/Api/ButtonField/ButtonField)|
 * |地址字段|[Address](/app-integration-dev/guide/dbsheet/Api/Api/AddressField/AddressField)|
 * |级联字段|[Cascade](/app-integration-dev/guide/dbsheet/Api/Api/CascadeField/CascadeField)|
 * |联系人字段|[Contact](/app-integration-dev/guide/dbsheet/Api/Api/ContactField/ContactField)|
 * |日期字段|[Date](/app-integration-dev/guide/dbsheet/Api/Api/DateField/DateField)|
 * |最后修改人/最后修改时间|[Watch](/app-integration-dev/guide/dbsheet/Api/Api/WatchedField/WatchedField)|
 * |公式字段|[Formula](/app-integration-dev/guide/dbsheet/Api/Api/FormulaField/FormulaField)|
 * |引用/查找引用/统计|[Lookup](/app-integration-dev/guide/dbsheet/Api/Api/LookupField/LookupField)|
 * |单向关联/双向关联|[Link](/app-integration-dev/guide/dbsheet/Api/Api/LinkField/LinkField)|
 * |自动任务|[Automation](/app-integration-dev/guide/dbsheet/Api/Api/AutomationField/AutomationField)|
 * |图片和附件|[Attachment](/app-integration-dev/guide/dbsheet/Api/Api/AttachmentField/AttachmentField)|
 * |超链接|[Url](/app-integration-dev/guide/dbsheet/Api/Api/UrlField/UrlField)|
 * |数字|[Number](/app-integration-dev/guide/dbsheet/Api/Api/NumberField/NumberField)|
 * |单选项/多选项|[Select](/app-integration-dev/guide/dbsheet/Api/Api/SelectField/SelectField)|
 * |等级|[Rating](/app-integration-dev/guide/dbsheet/Api/Api/RatingField/RatingField)|
 */
  interface FieldDescriptor {
    /**
     * 设置或读取 关联字段的关系组集合，如果有多个关系组，则这些关系组是或的关系
     *
     * ![alt text](https://cloudcdn.qwps.cn/open/_img/d3038f506e.png)
     */
    AutoLinkGroups: AutoLinkGroups;
    /**
     * 设置默认值
     */
    DefaultVal: string;
    /**
     * 设置默认值类型
     */
    DefaultValType: DbFieldDefaultValueType;
    /**
     * 字段的描述信息
     */
    Description: string;
    /**
     * 公式字段 返回公式的文本表达式
     */
    Formula: string;
    /**
     * 返回字段的ID，用于标识字段
     */
    readonly Id: any;
    /**
     * 标记字段是否同步字段
     */
    readonly IsSyncField: boolean;
    /**
     * 是否唯一值，禁止重复录入
     */
    IsValueUnique: boolean;
    /**
     * 设置或读取单向关联或双向关联字段的关联表格的Id
     */
    LinkSheet: number;
    /**
     * 设置或读取单向关联或双向关联字段的关联视图的id
     *
     * ![alt text](https://cloudcdn.qwps.cn/open/_img/750d9990de.png)
     */
    LinkView: string;
    /**
     * 字段名称
     */
    Name: string;
    /**
     * 数字格式，可以设置日期/时间/数值等字段的显示数字格式
     * 可以设置内置的格式
     * |字段类型|内建格式|
     * |---|---|
     * |货币|"￥","$","\"€\"","£"|
     *
     * ### 货币
     *
     * | 显示结果 | 内建格式  |
     * | -------- | --------- |
     * | "￥"     | "￥"      |
     * | "$"      | "$"       |
     * | "€"      | "\\"€\\"" |
     * | "£"      | "£"       |
     *
     * ### 数值
     *
     * | 显示结果     | 内建格式        |
     * | ------------ | --------------- |
     * | "1234"       | "0\_ "          |
     * | "1234.1"     | "0.0\_ "        |
     * | "1234.10 "   | "0.00\_ "       |
     * | "1234.100"   | "0.000\_ "      |
     * | "1234.1000"  | "0.0000\_ "     |
     * | "1,234"      | "#,##0\_ "      |
     * | "1,234.1"    | "#,##0.0\_ "    |
     * | "1,234.10"   | "#,##0.00\_ "   |
     * | "1,234.100"  | "#,##0.000\_ "  |
     * | "1,234.1000" | "#,##0.0000\_ " |
     *
     * ### 百分比
     *
     * | 显示结果   | 内建格式  |
     * | ---------- | --------- |
     * | "12%"      | "0%"      |
     * | "12.0%"    | "0.0%"    |
     * | "12.00% "  | "0.00%"   |
     * | "12.000%"  | "0.000%"  |
     * | "12.0000%" | "0.0000%" |
     *
     * ### 日期时间
     *
     * | 显示结果          | 内建格式          |
     * | ----------------- | ----------------- |
     * | 2023/04/18 10：09 | "yyyy/mm/dd h:mm" |
     */
    NumberFormat: string;
    /**
     * 级联选项各级选项的标题，最多可以设置四级标题
     */
    Title: any[];
    /**
     * 返回当前字段类型
     */
    Type: DbSheetFieldType;
    /**
     * 是否唯一值，禁止重复录入
     */
    ValueUnique: boolean;

    /**
     * 修改属性后调用Apply()方法使修改生效
     *
     * @returns ApiResult
     */
    Apply(): ApiResult;
    /**
     * 删除字段
     *
     * @returns boolean
     */
    Delete(RemoveReversedLink?: boolean): boolean;

    /**
     * 为 FieldDescriptor 添加 Delete 事件,当删除 FieldDescriptor 时触发。注意在脚本编辑器中使用时，脚本运行结束就会退出运行，这时可能回调无法被正常触发
     *
     * @param callback 事件回调，data 为事件返回数据
     */
    OnDelete(callback: (data: FieldDescriptorOnDeleteEventData) => void): EventContext;
    /**
     * 为 FieldDescriptor 添加 Update 事件,当更新 FieldDescriptor 时触发。注意在脚本编辑器中使用时，脚本运行结束就会退出运行，这时可能回调无法被正常触发
     *
     * @param callback 事件回调，data 为事件返回数据
     */
    OnUpdate(callback: (data: FieldDescriptor) => void): EventContext;
  }

/**
 * 字段描述的集合，保存了文档所有的字段的信息
 */
  interface FieldDescriptors {
    /** 直接调用集合，等价于 FieldDescriptors.Item(...)。 */
    (Index?: number | string): FieldDescriptor;
    /**
     * 字段描述的个数
     */
    Count: number;

    /**
     * 往表中新增新的字段
     *
     * @param FieldDescriptor 字段属性
     * @param Index Index为string时表示字段ID，number时表示字段索引，插入位置，未指定时插入到末尾
     * @returns ApiResult
     */
    AddField(FieldDescriptor: FieldDescriptor, Index?: string | number): ApiResult;
    /**
     * 删除字段
     *
     * @param FieldId 字段Id,可以通过字段名获取Sheet.FieldId(fieldName)
     * @param RemoveReversedLink 是否同时删除引用
     * @returns boolean
     */
    Delete(FieldId: string, RemoveReversedLink?: boolean): boolean;
    /**
     * FieldDescriptor对象
     *
     * @param Type FieldDescriptor的类型
     * @param Name FieldDescriptor的名称
     * @returns FieldDescriptor
     */
    FieldDescriptor(Type: any, Name: string): FieldDescriptor;
    /**
     * 返回字段的信息，可以通过 FieldDescriptors.Item() 返回某个字段的信息，也可以简化使用FieldDescriptors(Index) 来返回字段信息。
     *
     * @param Index Index为number类型时表示当前字段的索引，Index为字段串类型的时候表示字段的Id或@字段名称
     * @returns FieldDescriptor
     */
    Item(Index?: string | number): FieldDescriptor;

    /**
     * 为 FieldDescriptors 添加 Create 事件,当添加 FieldDescriptors 时触发。注意在脚本编辑器中使用时，脚本运行结束就会退出运行，这时可能回调无法被正常触发
     *
     * @param callback 事件回调，data 为事件返回数据
     */
    OnCreate(callback: (data: FieldDescriptor) => void): EventContext;
  }

/**
 * 网格视图列的集合，可以访问视图的列属性，通过Item方法访问列时，注意列如果是隐藏了就无法通过索引获取，只能通过名称或者字段ID来获取
 */
  interface Fields {
    /** 直接调用集合，等价于 Fields.Item(...)。 */
    (Index?: number | string): Field;
    /**
     * 字段描述的数量
     */
    Count: number;

    /**
     * 返回视图字段的信息，可以通过 Fields.Item() 返回某个字段的信息，也可以简化使用Fields(Index) 来返回字段信息。通过Item方法访问列时，注意列如果是隐藏了就无法通过索引获取，只能通过名称或者字段ID来获取。
     *
     * @param Index Index为number类型时表示当前字段的索引，Index为字段串类型的时候, 如果是以@开头则表示是字段名，否则表示字段的Id
     * @returns Field
     */
    Item(Index?: string | number): Field;
  }

